--定位
function UIPolePlotListDialog:OnBtnLocation()
    local id = roleStoryComp:GetLastChallengeQuestId(self._curChapterId)
    if checkNumber(id) == 0 then
        local t = QuestConfMgr:GetInstance():GetRoleStoryQuestIds(self._curChapterId)
        id = t[1]
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end
    
    local screenRect = UIModule.RootCanvas:GetComponent(typeof(RectTransform)).rect
    local targetX = -(checkNumber(vo.posX) - screenRect.width / 2)
    local targetY = -(checkNumber(vo.posY) - screenRect.height / 2)
    --self.Root.localPosition = Vector3(targetX, targetY, 0)
    self.Root.anchoredPosition = Vector2(targetX, targetY)
end 

