function UIPolePlotListDialog:FillQuests()
    for i = 1, self.Root.childCount do
        local go = self.Root:GetChild(i - 1)
        if go then
            CfUtils.SetActive(go, false)
        end
    end

    local isRestart = false

    for k, v in pairs(self._allQuestIds) do
        local go = self.Root.transform:Find("go"..k)
        if not go then
            if k == 1 then
                go = CfUtils.InstantiateGo(self.StartGroup, self.Root)
            else
                go = CfUtils.InstantiateGo(self.CardGroup1, self.Root)
            end
            if go then
                go.name = "go"..k
            end
        end
        CfUtils.SetActive(go, true)

        if k == 1 then
            self:FillHeadQuest(go, v, isRestart)
        else
            self:FillQuest(go, v, isRestart)
        end
    end

    --绘制结局
    local t = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleCgIds(self._curChapterId)
    if t then
        for k, v in pairs(t) do
            local go = self.Root.transform:Find("cg"..k)
            if not go then
                go = CfUtils.InstantiateGo(self.Root.transform:Find("CardGroup2"), self.Root)
                go.name = "cg"..k
            end
            KTool.SetActive(go, true)
            self:FillCgGo(go, v, isRestart)
        end
    end
    self.Root.sizeDelta = Vector2(self._maxX, self._maxY)

    self:OnBtnLocation()
end

function UIPolePlotListDialog:FillCgGo(go, id, isRestart)
    if not go or not id then
        return
    end

    local vo = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleCgVo(id)
    if not vo then
        return
    end
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(vo.chapterId)
    if not isPass then
        --CfUtils.SetActive(go, false)
        --return
    end

    local rootGo = go.transform:Find("CardGroup2")

    local isHas = QuestConfMgr:GetInstance():IsHasOverFinaleId(id)
    CfUtils.SetUISwitchImage(rootGo.transform:Find("ImgCg"), isHas and 1 or 2)

    CfUtils.SetActive(rootGo.transform:Find("ImgCg/ImgSmallCg"), isHas)

    CfUtils.SetActive(rootGo.transform:Find("CurrentStateAnim"), false)
    if isHas then 
        CfUtils.FillImage(rootGo.transform:Find("ImgCg/ImgSmallCg"), vo.cgIcon)
    end

    go.transform.localPosition = Vector3(vo.posX, vo.posY , 0)

    local screenRect = UIModule.RootCanvas:GetComponent(typeof(RectTransform)).rect

    if (vo.posX + screenRect.width / 2) > self._maxX then
        self._maxX = vo.posX + screenRect.width / 2
    end

    if (math.abs(vo.posY) + screenRect.height / 2) > self._maxY then
        self._maxY = math.abs(vo.posY) + screenRect.height / 2
    end

    self:FillCgLines(vo, isRestart)

    SetButtonAction(go, function()
        if not isHas then
            GameUtils.Toast(localize("尚未获得"))
        else
            UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotCGEndingDialog, parameters = {id = id, type = 1}},  {
                --{id = Constants.UITypeIds.UIMainBattlePanelDialog}
            })
            --self:OnBtnCollect()
        end
    end)
end

--第一个关卡特殊
function UIPolePlotListDialog:FillHeadQuest(go, id, isRestart)
    if not go or not id then
        return
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end
    local rootGo = go.transform:Find("StartGroup")

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(id)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(id)
    local status = 1
    if isPass then
        status = 2
    elseif not isUnlock then
        status = 3
    end

    CfUtils.FillText(rootGo.transform:Find("TxtName"), vo.name)
    
    CfUtils.SetUISwitchText(rootGo.transform:Find("TxtName"), status)
    CfUtils.SetUISwitchImage(rootGo.transform:Find("ImgBg"), status)

    go.transform.localPosition = Vector3(vo.posX, vo.posY , 0)
    self:FillLines(vo, isRestart)

    SetButtonAction(go, Bind(self, self.OnClick, id, true))

    CfUtils.SetActive(rootGo.transform:Find("ImgBlock"), not isPass and isUnlock)
    CfUtils.SetActive(rootGo.transform:Find("CurrentStateAnim"), not isPass and isUnlock)

    local screenRect = UIModule.RootCanvas:GetComponent(typeof(RectTransform)).rect
    self._maxX = vo.posX + screenRect.width / 2
    if (math.abs(vo.posY) + screenRect.height / 2) > self._maxY then
        self._maxY = math.abs(vo.posY) + screenRect.height / 2
    end
end

