function UIPolePlotListDialog:OnClick(questId, isTrue)
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(questId)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    if isPass then
        local lastId = roleStoryComp:GetLastChallengeQuestId(self._curChapterId)
        local lastVo = QuestConfMgr:GetInstance():GetQuestVoById(lastId)
        if lastVo then
            --通关结局了
            if checkNumber(lastVo.finale) == 1 then
                GameUtils.Toast(localize("已通关"))
                return 
            end
        end
        --起点不回溯
        if isTrue then
            GameUtils.Toast(localize("第一关无法返回，请再次游玩。"))
            return
        end

        GameUtils.SecondConfirm(localize("是否返回此关卡？"), function()
            roleStoryComp:BackQuestReq(questId, self._curChapterId, function()
                self:FillQuests(true)
            end)
        end, function()
            
        end, localize("当前章节进度将被重置"))
        return
    elseif not isUnlock then
        GameUtils.Toast(localize("该关卡未解锁"))
        return
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)

    local chapterVo = QuestConfMgr:GetInstance():GetRoleStoryChapterVo(self._curChapterId)
    KCookie.Set(Constants.UICacheDataKeys.ROLE_PLOT_CACHE, chapterVo.roleId)

    if checkNumber(vo.type) == Constants.QuestBattleType.Story then
        self:PlayPlot(vo, function(t)
            t = checkTable(t)
            --feelingNum = 20
            --optionIds = "240101003"
            roleStoryComp:StoryEnterReq(questId, t.Mood, t.Options, function()
                --self:PlayPassAni()
                self:PlayPassAni()
                self:FillQuests()

                self.Root.sizeDelta = Vector2(self._maxX, self._maxY)
                self:OnBtnLocation()
            end)
        end)
    else
        KCookie.Set("UIRolePlotDialogLastChallenge", self._curChapterId)
        FightPreWarMgr:GetInstance():FightEnter(questId)
    end
end

--播放剧情
function UIPolePlotListDialog:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, vo, endCb)
end

function UIPolePlotListDialog:PlayPloting(plotIds, vo, endCb)
    local chapterVo = QuestConfMgr:GetInstance():GetRoleStoryChapterVo(self._curChapterId)
    local ChapterUtils = import('Game.Chapter.ChapterUtils')
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        self._plotGo = go
    end, function(feelingNum, optionIds)
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            GameUtils.PlayMainBGM()
            if endCb then
                endCb(feelingNum, optionIds)
            end

            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            CfUtils.SetTopCommonActive(true, false)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, vo, endCb)
        end
    end, {roleId = chapterVo.roleId})
end

function UIPolePlotListDialog:FillCgLines(vo, isRestart)
    if isRestart then
        return
    end
    if not vo then
        return
    end

    local parIds = CfUtils.Split(vo.chapterId)
    if not parIds then
        return
    end

    for k, v in pairs(parIds) do
        local parVo = QuestConfMgr:GetInstance():GetQuestVoById(v)
        if parVo then
            local disY = checkNumber(vo.posY) - checkNumber(parVo.posY)
            local disX = checkNumber(vo.posX) - checkNumber(parVo.posX) - self.CardGroup1.sizeDelta.x/2 - self.CardGroup2.sizeDelta.x/2
            --一个直线
            if disY == 0 then
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.CardGroup1.sizeDelta.x / 2, checkNumber(parVo.posY)), disX, 0)
            else
                local dir = disY > 0 and 1 or -1
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.CardGroup1.sizeDelta.x / 2, checkNumber(vo.posY)),disX, 0)

                disY = math.abs(disY)
                local ang = ((dir == 1) and 90 or -90)
                local y = (checkNumber(parVo.posY) + checkNumber(vo.posY))/2
                if dir == 1 then
                    y = y - disY/2
                else
                    y = y + disY/2
                end
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.CardGroup1.sizeDelta.x / 2, y), disY, ang)
            end
        end
    end
end

function UIPolePlotListDialog:FillLines(vo, isRestart)
    if isRestart then
        return
    end
    if not vo then
        return
    end

    local parIds = CfUtils.Split(vo.unlockNum1)
    if not parIds then
        return
    end
    
    for k, v in pairs(parIds) do
        local parVo = QuestConfMgr:GetInstance():GetQuestVoById(v)
        if parVo then
            local disY = checkNumber(vo.posY) - checkNumber(parVo.posY)
            local disX = checkNumber(vo.posX) - checkNumber(parVo.posX) - self.StartGroup.sizeDelta.x
            --一个直线
            if disY == 0 then
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.StartGroup.sizeDelta.x / 2, checkNumber(parVo.posY)), disX, 0)
            else
                local dir = disY > 0 and 1 or -1
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.StartGroup.sizeDelta.x / 2, checkNumber(vo.posY)),disX, 0)

                disY = math.abs(disY)
                --self:FillLine(Vector2(checkNumber(parVo.posX) + self.StartGroup.sizeDelta.x / 2 + disX / 2, checkNumber(vo.posY)), disX/2, 0)
                
                local ang = ((dir == 1) and 90 or -90)
                local y = (checkNumber(parVo.posY) + checkNumber(vo.posY))/2
                if dir == 1 then
                    y = y - disY/2
                else
                    y = y + disY/2
                end
                self:FillLine(Vector2(checkNumber(parVo.posX) + self.StartGroup.sizeDelta.x / 2, y), disY, ang)
            end
        end
    end
end

function UIPolePlotListDialog:FillLine(pos, len, ang)
    local go = self.Root.transform:Find(pos.x..pos.y..len..ang)
    if not go then
        go = CfUtils.InstantiateGo(self.ImgLineNode, self.Root)
    end
    go.name = pos.x..pos.y..len..ang
    CfUtils.SetActive(go, true)
    go.transform.localRotation = Quaternion.Euler(0, 0, ang)
    go.transform.localPosition = Vector3(pos.x, pos.y , 0)
    local y = go:GetComponent(typeof(RectTransform)).sizeDelta.y
    go:GetComponent(typeof(RectTransform)).sizeDelta = Vector2(len, y)
end

