--通关的动画表现
function UIPolePlotListDialog:PlayPassAni()
    local id = KCookie.Get("RoleStoryPassQuest")
    if checkNumber(id) <= 0 then
        return
    end
    KCookie.Set("RoleStoryPassQuest", 0)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end
    local ind = table.keyof(self._allQuestIds, checkString(id))
    ind = checkNumber(ind)
    if ind > 0 then
        local go = self.Root.transform:Find("go"..ind)
        if go then
            if ind == 1 then
                self:FillHeadQuest(go, id, true)
            else
                self:FillQuest(go, id, true)
            end
        end

        local t = roleStoryComp:GetUnlockQuestIds(self._curChapterId)
        if t then
            for k, v in pairs(t) do
                ind = table.keyof(self._allQuestIds, checkString(v))
                ind = checkNumber(ind)
                if ind > 0 then
                    local go = self.Root.transform:Find("go"..ind)
                    if go then
                        if ind == 1 then
                            self:FillHeadQuest(go, v)
                        else
                            self:FillQuest(go, v)
                        end
                    end
                end
            end
        end
    end
    
    --结局了
    if checkNumber(vo.finale) == 1 then
        local t = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleCgIds(self._curChapterId)
        if t then
            for k, v in pairs(t) do
                local go = self.Root.transform:Find("cg"..k)
                if not go then
                    go = CfUtils.InstantiateGo(self.Root.transform:Find("CardGroup2"), self.Root)
                    go.name = "cg"..k
                end
                self:FillCgGo(go, v, true)
            end
        end

        local allNum, hasNum = QuestConfMgr:GetInstance():GetRoleStoryChapterOverFinaleIdNum(self._curChapterId)
        CfUtils.FillText(self.TxtNum, hasNum.."/"..allNum)
        
        local cgId = QuestConfMgr:GetInstance():GetOverFinaleCgIdByQuestId(id)
        UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotCGEndingDialog, parameters = {id = cgId, type = 2}},  {
            --{id = Constants.UITypeIds.UIMainBattlePanelDialog}
        })
    end
end

function UIPolePlotListDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KCookie.Set(Constants.UICacheDataKeys.ROLE_PLOT_CACHE, 0)
        local isFinish = false
        GameUtils.Request(Interfaces.CatQuestHome, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end

            local jsonData = response.data
            roleStoryComp:InitialRoleStoryCopy(jsonData)

            isFinish = true
        end)
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
        end

        local argument = self.controller.Argument.parameters
        if argument then
            self._curChapterId = checkNumber(argument.id)  --副本类型
        end
    
        if checkNumber(self._curChapterId) == 0 then
            return
        end
    
        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIPolePlotListDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIPolePlotListDialog
